python3 -c "
import zipfile, xml.etree.ElementTree as ET
NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
def col(ref): return ''.join(c for c in ref if c.isalpha())
with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows = {}
for row in root.findall('.//m:sheetData/m:row', NS):
    r = int(row.get('r')); cells = {}
    for c in row.findall('m:c', NS):
        v = c.find('m:v', NS); is_ = c.find('m:is', NS)
        if v is not None and v.text is not None: cells[col(c.get('r'))] = v.text
        elif is_ is not None:
            t = is_.find('m:t', NS)
            cells[col(c.get('r'))] = t.text if t is not None and t.text is not None else ''
    rows[r] = cells
print('=== ALL ROWS ===')
for r in sorted(rows):
    print(r, {k: rows[r][k] for k in sorted(rows[r])})
exp = []
for r in range(11, 23):
    c = rows.get(r, {})
    if 'C' in c: exp.append((c.get('A',''), c.get('B',''), float(c['C'])))
by_cat, total = {}, 0.0
print('=== EXPENSES (rows 11-22) ===')
for cat, item, amt in exp:
    print(f'{cat:<16}{item:<16}{amt:>10,.2f}')
    by_cat[cat] = by_cat.get(cat, 0.0) + amt; total += amt
print('=== BY CATEGORY ===')
for cat, amt in sorted(by_cat.items()): print(f'{cat:<16}{amt:>10,.2f}')
print(f'TOTAL EXPENSES (ALL CATEGORIES): {total:,.2f}')
print('Existing C23 (Total Expenses formula):', rows.get(23, {}).get('C'))
inc = sum(float(rows[r]['B']) for r in range(4, 8) if 'B' in rows.get(r, {}))
print(f'Total Income: {inc:,.2f} | Balance: {inc - total:,.2f}')
"
